import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        Arrays.sort(a);
        // Scan distinct runtimes from the largest: best[t] = count[t] + best[t + 1] when t + 1 exists.
        long answer = 0, nextValue = Long.MIN_VALUE, nextBest = 0;
        for (int j = n - 1; j >= 0;) {
            int i = j;
            while (i >= 0 && a[i] == a[j]) i--;
            long best = (j - i) + (nextValue == a[j] + 1 ? nextBest : 0);
            answer = Math.max(answer, best);
            nextValue = a[j];
            nextBest = best;
            j = i;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	slices.Sort(a)
	// Scan distinct runtimes from the largest: best[t] = count[t] + best[t+1] when t+1 exists.
	answer, nextBest := int64(0), int64(0)
	nextValue := int64(-1)
	for j := n - 1; j >= 0; {
		i := j
		for i >= 0 && a[i] == a[j] {
			i--
		}
		best := int64(j - i)
		if nextValue == a[j]+1 {
			best += nextBest
		}
		answer = max(answer, best)
		nextValue, nextBest = a[j], best
		j = i
	}
	fmt.Println(answer)
}
